Here is Benchmark for 
```
func (gc *generalCICollator) Compare(a, b string) int {
	aRune := []rune(a)
	bRune := []rune(b)
	aLen := len(aRune)
	bLen := len(bRune)

	for i := 0; i < aLen && i < bLen; i++ {
		cmp := int(convertRune(aRune[i])) - int(convertRune(bRune[i]))
		if cmp != 0 {
			return sign(cmp)
		}
	}

	return sign(aLen - bLen)
}
```

100Diff means comparing two different strings with length 100
100eEqual means comparing two eqal strings with length 100
Simple5 means comparing two strings with length 5
50Equal50Diff means comparing two string with length 100 and their first 50 chars are equal.
```
