BenchmarkComapreSimple5-4               1000000000               0.00757 ns/op
BenchmarkComapre50Equal50Diff-4         1000000000               0.0711 ns/op

```

And here is the Benchmark for
```
func (gc *generalCICollator) Compare(a, b string) int {
	for len(a) > 0 && len(b) > 0 {
		r1, size1 := utf8.DecodeRuneInString(a)
		r2, size2 := utf8.DecodeRuneInString(b)

		cmp := int(convertRune(r1)) - int(convertRune(r2))
		if cmp != 0 {
			return sign(cmp)
		}
		a = a[size1:]
		b = b[size2:]
	}
	return sign(len(a) - len(b))
}
```
